source_materials.text:
#AWS Account Id
data "aws_caller_identity" "this" {}


data "aws_ami" "ubuntu" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["ubuntu/images/hvm-ssd-gp3/ubuntu-noble-24.04-amd64-server-*"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}


data "archive_file" "app" {
  type        = "zip"
  source_dir  = "../assets/rce_app/"
  output_path = "../assets/app.zip"
}

resource "aws_iam_role" "ec2" {
  depends_on = [
    aws_iam_policy.ec2_rds
  ]

  name                  = "cg-ec2-role-${var.cgid}"
  force_detach_policies = true

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Effect = "Allow"
      }
    ]
  })
}


resource "aws_iam_role_policy_attachments_exclusive" "ec2" {
  role_name = aws_iam_role.ec2.name
  policy_arns = [
    "arn:aws:iam::aws:policy/AmazonS3FullAccess",
    aws_iam_policy.ec2_rds.arn
  ]
}


#IAM Policy for EC2-RDS
resource "aws_iam_policy" "ec2_rds" {
  name        = "cg-ec2-rds-policy"
  description = "cg-ec2-rds-policy"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeVpcs",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "rds:DescribeDBInstances"
        ],
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}


#IAM Instance Profile
resource "aws_iam_instance_profile" "ec2" {
  name = "cg-ec2-instance-profile-${var.cgid}"
  role = aws_iam_role.ec2.name
}


#Security Groups
resource "aws_security_group" "ec2_ssh" {
  name        = "cg-ec2-ssh-${var.cgid}"
  description = "CloudGoat ${var.cgid} Security Group for EC2 Instance over SSH"
  vpc_id      = aws_vpc.this.id

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.cg_whitelist
  }

  egress {
    from_port = 0
    to_port   = 0
    protocol  = "-1"
    cidr_blocks = [
      "0.0.0.0/0"
    ]
  }

  tags = {
    Name = "cg-ec2-ssh-${var.cgid}"
  }
}

resource "aws_security_group" "ec2_http" {
  name        = "cg-ec2-http-${var.cgid}"
  description = "CloudGoat ${var.cgid} Security Group for EC2 Instance over HTTP"
  vpc_id      = aws_vpc.this.id

  ingress {
    from_port = 9000
    to_port   = 9000
    protocol  = "tcp"
    security_groups = [
      aws_security_group.lb_http.id
    ]
  }

  egress {
    from_port = 0
    to_port   = 0
    protocol  = "-1"
    security_groups = [
      aws_security_group.lb_http.id
    ]
  }

  tags = {
    Name = "cg-ec2-http-${var.cgid}"
  }
}


#AWS Key Pair
resource "aws_key_pair" "this" {
  key_name   = "cg-ec2-key-pair-${var.cgid}"
  public_key = file(var.ssh_public_key)
}


#EC2 Instance
resource "aws_instance" "ubuntu" {
  ami                         = data.aws_ami.ubuntu.image_id
  instance_type               = "t3.micro"
  iam_instance_profile        = aws_iam_instance_profile.ec2.name
  subnet_id                   = aws_subnet.public_1.id
  associate_public_ip_address = true
  key_name                    = aws_key_pair.this.key_name

  vpc_security_group_ids = [
    aws_security_group.ec2_ssh.id,
    aws_security_group.ec2_http.id
  ]

  root_block_device {
    volume_type           = "gp2"
    volume_size           = 8
    delete_on_termination = true
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "optional"
    http_put_response_hop_limit = 2
  }

  provisioner "file" {
    source      = data.archive_file.app.output_path
    destination = "/home/ubuntu/app.zip"
    connection {
      type        = "ssh"
      user        = "ubuntu"
      private_key = file(var.ssh_private_key)
      host        = self.public_ip
    }
  }

  user_data = <<-EOF
        #!/bin/bash
        apt-get update
        curl -sL https://deb.nodesource.com/setup_8.x | sudo -E bash -
        DEBIAN_FRONTEND=noninteractive apt-get install -y nodejs postgresql-client unzip
        psql postgresql://${var.rds_username}:${var.rds_password}@${aws_db_instance.postgres.endpoint}/cloudgoat \
        -c "CREATE TABLE sensitive_information (name VARCHAR(50) NOT NULL, value VARCHAR(50) NOT NULL);"
        psql postgresql://${var.rds_username}:${var.rds_password}@${aws_db_instance.postgres.endpoint}/cloudgoat \
        -c "INSERT INTO sensitive_information (name,value) VALUES ('Super-secret-passcode',E'V\!C70RY-4hy2809gnbv40h8g4b');"
        sleep 15s
        cd /home/ubuntu
        unzip app.zip -d ./app
        cd app
        node index.js &
        echo -e "\n* * * * * root node /home/ubuntu/app/index.js &\n* * * * * root sleep 10; curl GET http://${aws_lb.this.dns_name}/mkja1xijqf0abo1h9glg.html &\n* * * * * root sleep 10; node /home/ubuntu/app/index.js &\n* * * * * root sleep 20; node /home/ubuntu/app/index.js &\n* * * * * root sleep 30; node /home/ubuntu/app/index.js &\n* * * * * root sleep 40; node /home/ubuntu/app/index.js &\n* * * * * root sleep 50; node /home/ubuntu/app/index.js &\n" >> /etc/crontab
        EOF

  volume_tags = {
    Name = "CloudGoat ${var.cgid} EC2 Instance Root Device"
  }
  tags = {
    Name = "cg-ubuntu-ec2-${var.cgid}"
  }
}

# Lara IAM User & Permissions
resource "aws_iam_user" "lara" {
  name = "lara"
}

resource "aws_iam_access_key" "lara" {
  user = aws_iam_user.lara.name
}

resource "aws_iam_policy" "lara" {
  name        = "cg-lara-s3-policy"
  description = "cg-lara-policy"

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action   = "s3:ListBucket"
        Effect   = "Allow"
        Resource = aws_s3_bucket.logs.arn
      },
      {
        Action   = "s3:GetObject"
        Effect   = "Allow"
        Resource = "${aws_s3_bucket.logs.arn}/*"
      },
      {
        Action   = "s3:ListAllMyBuckets"
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeVpcs",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "rds:DescribeDBInstances",
          "elasticloadbalancing:DescribeLoadBalancers"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "lara" {
  user       = aws_iam_user.lara.name
  policy_arn = aws_iam_policy.lara.arn
}



# McDuck IAM User & Permissions
resource "aws_iam_user" "mcduck" {
  name = "McDuck"
}

resource "aws_iam_access_key" "mcduck" {
  user = aws_iam_user.mcduck.name
}

resource "aws_iam_policy" "mcduck" {
  name        = "cg-mcduck-s3-policy"
  description = "cg-mcduck-policy"

  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Action   = "s3:ListBucket"
        Effect   = "Allow"
        Resource = aws_s3_bucket.keystore.arn
      },
      {
        Action   = "s3:GetObject"
        Effect   = "Allow"
        Resource = "${aws_s3_bucket.keystore.arn}/*"
      },
      {
        Action   = "s3:ListAllMyBuckets"
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "ec2:DescribeInstances",
          "ec2:DescribeVpcs",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "rds:DescribeDBInstances"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "mcduck" {
  user       = aws_iam_user.mcduck.name
  policy_arn = aws_iam_policy.mcduck.arn
}

#Security Groups
resource "aws_security_group" "lb_http" {
  name        = "cg-lb-http-${local.cgid_suffix}"
  description = "CloudGoat ${var.cgid} Security Group for Application Load Balancer over HTTP"
  vpc_id      = aws_vpc.this.id
  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = var.cg_whitelist
  }

  egress {
    from_port = 0
    to_port   = 0
    protocol  = "-1"
    cidr_blocks = [
      "0.0.0.0/0"
    ]
  }

  tags = {
    Name = "cg-lb-http-${local.cgid_suffix}"
  }
}


#Application Load Balancer
resource "aws_lb" "this" {
  name               = "cg-lb-${local.cgid_suffix}"
  internal           = false
  load_balancer_type = "application"
  ip_address_type    = "ipv4"
  access_logs {
    bucket  = aws_s3_bucket.logs.bucket
    prefix  = "cg-lb-logs"
    enabled = true
  }
  security_groups = [
    aws_security_group.lb_http.id
  ]
  subnets = [
    aws_subnet.public_1.id,
    aws_subnet.public_2.id
  ]
}

#Target Group
resource "aws_lb_target_group" "this" {
  # Note: the name cannot be more than 32 characters
  name        = "cg-tg-${local.cgid_suffix}"
  port        = 9000
  protocol    = "HTTP"
  vpc_id      = aws_vpc.this.id
  target_type = "instance"
}

#Target Group Attachment
resource "aws_lb_target_group_attachment" "this" {
  target_group_arn = aws_lb_target_group.this.arn
  target_id        = aws_instance.ubuntu.id
  port             = 9000
}

#Load Balancer Listener
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.this.arn
  port              = 80
  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.this.arn
  }
}

locals {
  # Ensure resource suffixes the bucket suffix doesn't contain anything else than
  # lowercase letters, numbers, and hyphens
  # Used for RDS, load balancer and S3
  cgid_suffix = replace(var.cgid, "/[^a-z0-9-]/", "-")
}

output "cloudgoat_output_lara_access_key_id" {
  value = aws_iam_access_key.lara.id
}

output "cloudgoat_output_lara_secret_key" {
  value     = aws_iam_access_key.lara.secret
  sensitive = true
}


output "cloudgoat_output_mcduck_access_key_id" {
  value = aws_iam_access_key.mcduck.id
}

output "cloudgoat_output_mcduck_secret_key" {
  value     = aws_iam_access_key.mcduck.secret
  sensitive = true
}

#Logs S3 Bucket
resource "aws_s3_bucket" "logs" {
  bucket        = "cg-logs-s3-bucket-${local.cgid_suffix}"
  force_destroy = true
  tags = {
    Description = "CloudGoat ${var.cgid} S3 Bucket used for ALB Logs"
  }
}

#Logs S3 Bucket Policy
resource "aws_s3_bucket_policy" "logs_policy" {
  bucket = aws_s3_bucket.logs.id
  policy = jsonencode({
    Id      = "Policy1558803362844"
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "load-balancer-policy"
        Action   = "s3:PutObject"
        Effect   = "Allow"
        Resource = "${aws_s3_bucket.logs.arn}/cg-lb-logs/AWSLogs/${data.aws_caller_identity.this.account_id}/*"
        Principal = {
          AWS = "arn:aws:iam::127311923021:root"
        }
      }
    ]
  })
}

resource "aws_s3_object" "lb_logs" {
  bucket = aws_s3_bucket.logs.id
  key    = "cg-lb-logs/AWSLogs/${data.aws_caller_identity.this.account_id}/elasticloadbalancing/${var.region}/2019/06/19/555555555555_elasticloadbalancing_us-east-1_app.cg-lb-cgidp347lhz47g.d36d4f13b73c2fe7_20190618T2140Z_10.10.10.100_5m9btchz.log"
  content = templatefile("../assets/elasticloadbalancing.log", {
    cgid              = "cg-lb-${local.cgid_suffix}"
    load_balancer_dns = aws_lb.this.dns_name
    target_group_arn  = aws_lb_target_group.this.arn
  })
}


#Secret S3 Bucket
resource "aws_s3_bucket" "secret" {
  bucket        = "cg-secret-s3-bucket-${local.cgid_suffix}"
  force_destroy = true
  tags = {
    Description = "CloudGoat ${var.cgid} S3 Bucket used for storing a secret"
  }
}

resource "aws_s3_object" "db_credentials" {
  bucket = aws_s3_bucket.secret.id
  key    = "db.txt"
  source = "../assets/db.txt"
}


#Keystore S3 Bucket
resource "aws_s3_bucket" "keystore" {
  bucket        = "cg-keystore-s3-bucket-${local.cgid_suffix}"
  force_destroy = true
  tags = {
    Description = "CloudGoat ${var.cgid} S3 Bucket used for storing ssh keys"
  }
}

resource "aws_s3_object" "ssh_private_key" {
  bucket = aws_s3_bucket.keystore.id
  key    = "cloudgoat"
  source = var.ssh_private_key
}

resource "aws_s3_object" "ssh_public_key" {
  bucket = aws_s3_bucket.keystore.id
  key    = "cloudgoat.pub"
  source = var.ssh_public_key
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}


provider "aws" {
  profile = var.profile
  region  = var.region

  default_tags {
    tags = {
      Stack    = var.stack-name
      Scenario = var.scenario-name
    }
  }
}

variable "profile" {
  description = "The AWS profile to use."
  type        = string
}

variable "region" {
  description = "The AWS region to deploy resources to."
  default     = "us-east-1"
  type        = string
}

variable "cgid" {
  description = "CGID variable for unique naming."
  type        = string
}

variable "cg_whitelist" {
  description = "User's public IP address"
  type        = list(string)
}

variable "rds_username" {
  description = "RDS PostgreSQL instance username"
  default     = "cgadmin"
  type        = string
}

variable "rds_password" {
  description = "RDS PostgreSQL instance password"
  default     = "Purplepwny2029"
  type        = string
}

variable "ssh_public_key" {
  description = "Where to store the public key"
  default     = "../cloudgoat.pub"
  type        = string
}

variable "ssh_private_key" {
  description = "Where to store the private key"
  default     = "../cloudgoat"
  type        = string
}

variable "stack-name" {
  description = "Name of the stack."
  default     = "CloudGoat"
  type        = string
}

variable "scenario-name" {
  description = "Name of the scenario."
  default     = "rce-web-app"
  type        = string
}

#VPC
resource "aws_vpc" "this" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_hostnames = true
  tags = {
    Name = "CloudGoat ${var.cgid}"
  }
}

#Internet Gateway
resource "aws_internet_gateway" "this" {
  vpc_id = aws_vpc.this.id
  tags = {
    Name = "CloudGoat ${var.cgid}"
  }
}


#Public Subnets
resource "aws_subnet" "public_1" {
  availability_zone = "${var.region}a"
  cidr_block        = "10.0.10.0/24"
  vpc_id            = aws_vpc.this.id
  tags = {
    Name = "CloudGoat Public Subnet #1"
  }
}

resource "aws_subnet" "public_2" {
  availability_zone = "${var.region}b"
  cidr_block        = "10.0.20.0/24"
  vpc_id            = aws_vpc.this.id
  tags = {
    Name = "CloudGoat Public Subnet #2"
  }
}

#Private Subnets
resource "aws_subnet" "private_1" {
  availability_zone = "${var.region}a"
  cidr_block        = "10.0.30.0/24"
  vpc_id            = aws_vpc.this.id
  tags = {
    Name = "CloudGoat Private Subnet #1"
  }
}

resource "aws_subnet" "private_2" {
  availability_zone = "${var.region}b"
  cidr_block        = "10.0.40.0/24"
  vpc_id            = aws_vpc.this.id
  tags = {
    Name = "CloudGoat Private Subnet #2"
  }
}


#Public Subnet Routing Table
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.this.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.this.id
  }

  tags = {
    Name = "CloudGoat Route Table for Public Subnet"
  }
}

#Private Subnet Routing Table
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.this.id
  tags = {
    Name = "CloudGoat Route Table for Private Subnet"
  }
}


#Public Subnets Routing Associations
resource "aws_route_table_association" "public_1" {
  subnet_id      = aws_subnet.public_1.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_2" {
  subnet_id      = aws_subnet.public_2.id
  route_table_id = aws_route_table.public.id
}


#Private Subnets Routing Associations
resource "aws_route_table_association" "private_1" {
  subnet_id      = aws_subnet.private_1.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_2" {
  subnet_id      = aws_subnet.private_2.id
  route_table_id = aws_route_table.private.id
}
